/*
  холст.js — ВИД ОТ ГЕРОЯ. Мир на холсте 320×200, крупной точкой.

  Чем отличается от соседей: карта.js держит устройство мира — дороги,
  поиск пути, движение героя. Этот файл ничего про мир не решает, он
  только показывает: получает от карты, где герой и по какой дороге
  идёт, и рисует то, что он видит перед собой.

  МИРОВЫХ КООРДИНАТ ЗДЕСЬ НЕТ. Всё считается от экранной строки: где
  середина дороги, какой она ширины, что стоит по сторонам. Отказ от
  мировых координат — решение задания: настоящий поворот камеры с
  обходом вокруг дома запрещён разделом 12, а дешёвый поворот в такой
  рисовке делается переводом двух чисел.

  Шаг первый: небо, земля, дорога, горизонт. Больше ничего.
*/

'use strict';

window.ХОЛСТ = (function () {

const НАСТРОЙКИ = window.МИР_НАСТРОЙКИ;

let холст = null, кисть = null, кадр = 0;

/* ═══ 1 · КРАСКИ ═══════════════════════════════════════════════════ */

const мешать = (а, б, доля) =>
  а.map((знач, и) => Math.round(знач + (б[и] - знач) * доля));

const цвет = (краска) => 'rgb(' + краска[0] + ',' + краска[1] + ',' + краска[2] + ')';

/* ═══ 2 · ПЕРСПЕКТИВА ══════════════════════════════════════════════
   Глубина: 0 у горизонта, 1 у нижнего края. Всё остальное — от неё. */

function глубина(строка) {
  const х = НАСТРОЙКИ.холст;
  const от = х.горизонт + х.отступГоризонта;
  return Math.max(0, Math.min(1, (строка - от) / (х.высота - от)));
}

const ширинаДороги = (строка) => {
  const х = НАСТРОЙКИ.холст;
  return х.дорогаУГоризонта + Math.pow(глубина(строка), х.законСужения) * х.дорогаРазмах;
};

/*  СЕРЕДИНА ДОРОГИ. Изгиб идёт от кривизны кольца, на котором стоит
    герой: чем кольцо теснее, тем сильнее ведёт. На луче и тропке
    изгиб равен нулю, и дорога идёт прямой.                        */
function серединаДороги(строка, изгиб) {
  const х = НАСТРОЙКИ.холст;
  const г = глубина(строка);
  return х.ширина / 2 +
    Math.sin(г * х.изгибЧастота + х.изгибСдвиг) * х.изгибРазмах * г * изгиб +
    Math.sin(г * х.изгибРябьЧастота) * х.изгибРябь * г * изгиб;
}

/* ═══ 3 · РИСОВАНИЕ ════════════════════════════════════════════════ */

function точки(x, y, ш, в, краска) {
  кисть.fillStyle = краска;
  кисть.fillRect(Math.round(x), Math.round(y), Math.max(1, Math.round(ш)),
                 Math.max(1, Math.round(в)));
}

function небо(п) {
  const х = НАСТРОЙКИ.холст;
  for (let y = 0; y < х.горизонт; y++) {
    const доля = Math.pow(y / х.горизонт, х.небоСтепень);
    точки(0, y, х.ширина, 1, цвет(мешать(п.небоВерх, п.небоНиз, доля)));
  }
  /* зарево у самого горизонта: небо у земли всегда светлее */
  for (let y = х.горизонт - х.заревоВысота; y < х.горизонт; y++) {
    кисть.globalAlpha = ((y - (х.горизонт - х.заревоВысота)) / х.заревоВысота) * х.заревоСила;
    точки(0, y, х.ширина, 1, цвет(п.зарево));
    кисть.globalAlpha = 1;
  }
}

function земля(п) {
  const х = НАСТРОЙКИ.холст;
  for (let y = х.горизонт; y < х.высота; y++) {
    точки(0, y, х.ширина, 1, цвет(мешать(п.землД, п.землБ, глубина(y))));
  }
}

/*  Дорога. Кромки протоптаны светлее, по середине две колеи темнее —
    это то, что отличает тракт от полосы краски.                   */
function дорога(п, изгиб) {
  const х = НАСТРОЙКИ.холст;
  for (let y = х.горизонт + х.отступГоризонта; y < х.высота; y++) {
    const ц = серединаДороги(y, изгиб), ш = ширинаДороги(y), г = глубина(y);
    const полотно = мешать(п.дорога, мешать(п.дорога, п.землБ, х.дорогаДаль), г);
    точки(ц - ш / 2, y, ш, 1, цвет(полотно));

    const кромка = цвет(мешать(п.дорога, п.землБ, х.кромкаСвет));
    точки(ц - ш / 2, y, ш * х.кромкаДоля, 1, кромка);
    точки(ц + ш / 2 - ш * х.кромкаДоля, y, ш * х.кромкаДоля, 1, кромка);

    кисть.globalAlpha = х.колеяПрозрачность;
    const колея = цвет(мешать(п.дорога, [0, 0, 0], х.колеяТень));
    точки(ц - ш * х.колеяСлева, y, ш * х.колеяДоля, 1, колея);
    точки(ц + ш * х.колеяСправа, y, ш * х.колеяДоля, 1, колея);
    кисть.globalAlpha = 1;
  }
}

/* ═══ 4 · ДОМА ═════════════════════════════════════════════════════
   Японские, с широкими крышами. Ярус устроен сверху вниз: крыша
   ступенями с приподнятыми концами, снег на левом скате, конёк
   светлее, корпус с балкой и стойками, три бумажных окна.

   Верхний ярус уже нижнего. Ярусов даёт кольцо, а не случай, — это
   решает карта, здесь мы только рисуем.                            */

/*  Устойчивая случайность: одно и то же число для одного и того же
    дома. Обычный бросок дал бы дрожь на каждом кадре.             */
const порознь = (и, ширина) => {
  const с = НАСТРОЙКИ.холст.случайность;
  return ((и * с.множитель + Math.round(ширина) * с.шаг) % с.делитель) / с.делитель;
};

function крышаЯруса(п, x, верх, шя, св, вк) {
  const я = НАСТРОЙКИ.холст.дом.ярус;
  for (let р = 0; р < вк; р++) {
    const доля = р / вк;
    const ш2 = Math.round((шя + св * 2) * (1 - доля * я.сужениеКрыши));
    const подъём = Math.round(Math.pow(1 - доля, я.законПодъёма) * шя * я.подъёмКонцов);
    точки(x - ш2 / 2, верх - р - 1, ш2, 1, цвет(п.крыша));
    /*  СНЕГ ЛОЖИТСЯ НА САМ СКАТ, строку за строкой, а не полосой
        поверх узкой верхушки: полоса торчала бы в стороне от крыши
        и читалась бы как оборванная черта в воздухе.

        Слева — потому что свет слева сверху, это правило мира.   */
    точки(x - ш2 / 2, верх - р - 1, Math.round(ш2 * я.снегДоля), 1,
          цвет(мешать(п.крыша, п.шапка, я.снегСила)));
    if (р < 2) {   // концы приподняты только у самого низа крыши
      точки(x - ш2 / 2 - подъём, верх - р - 1 - Math.round(подъём / 2), подъём + 1, 1, цвет(п.крыша));
      точки(x + ш2 / 2, верх - р - 1 - Math.round(подъём / 2), подъём + 1, 1, цвет(п.крыша));
    }
  }
  /* конёк светлее крыши */
  точки(x - Math.round(шя * я.конёкШирина / 2), верх - вк - 1,
        Math.round(шя * я.конёкШирина), 2,
        цвет(мешать(п.крыша, п.шапка, я.конёкСвет)));
}

function окнаЯруса(п, дом, x, верх, шя, вя, номерЯруса) {
  const о = НАСТРОЙКИ.холст.дом.окно;
  const ош = Math.max(2, Math.round(шя * о.ширина));
  const ов = Math.max(2, Math.round(вя * о.высота));
  for (let и = 0; и < о.сколько; и++) {
    const ох = Math.round(x - шя / 2 + шя * о.отступ + и * шя * о.шаг);
    const оу = Math.round(верх + вя * о.сверху);
    if (дом.открыт) {
      /*  Окна мерцают вразнобой: у каждого свой сдвиг по кадру,
          иначе весь порядок домов моргает разом.                */
      const н = НАСТРОЙКИ.холст.дом;
      const дрожь = (Math.sin((кадр + и * н.сдвигОкна + номерЯруса * н.сдвигЯруса) /
                              о.мерцаниеШаг) + 1) / 2;
      кисть.globalAlpha = о.свет + дрожь * о.мерцание;
      точки(ох, оу, ош, ов, цвет(п.теплоС));
      кисть.globalAlpha = о.отсвет;
      const поле = НАСТРОЙКИ.холст.дом.отсветПоле;
      точки(ох - поле, оу - поле, ош + поле * 2, ов + поле * 2, цвет(п.тепло));
      кисть.globalAlpha = 1;
    } else {
      точки(ох, оу, ош, ов, цвет(мешать(п.деревоТ, [0, 0, 0], о.темнота)));
    }
    if (шя > о.переплётОт) {   // переплёт различим только вблизи
      точки(ох, оу + Math.round(ов / 2), ош, 1, цвет(п.деревоТ));
      точки(ох + Math.round(ош / 2), оу, 1, ов, цвет(п.деревоТ));
    }
  }
}

function дом(п, д) {
  const н = НАСТРОЙКИ.холст.дом;
  const я = н.ярус, x = д.x, ш = д.ш;

  /* тень под домом: без неё дом висит над землёй */
  кисть.globalAlpha = н.тень.сила;
  точки(x - ш * н.тень.доля / 2, д.y - 1, ш * н.тень.доля, н.тень.высота,
        цвет(п.тень));
  кисть.globalAlpha = 1;

  let низ = д.y;
  for (let номер = 0; номер < д.ярусов; номер++) {
    const шя = Math.round(ш * Math.pow(я.сжатие, номер));
    const вя = Math.round(шя * я.высота);
    const св = Math.round(шя * я.свес), вк = Math.round(шя * я.крыша);
    const верх = низ - вя;

    точки(x - шя / 2, верх, шя, вя, цвет(п.дерево));
    /* левая кромка светлее: свет слева сверху */
    точки(x - шя / 2, верх, Math.max(1, шя * я.кромкаСлева), вя,
          цвет(мешать(п.дерево, п.шапка, я.кромкаСвет)));
    /* холодная подсветка снизу, против тёплого из окон */
    кисть.globalAlpha = н.подсветкаСнизу.сила;
    точки(x - шя / 2, верх + вя * н.подсветкаСнизу.от, шя, вя * н.подсветкаСнизу.доля,
          цвет(п.подсветка));
    кисть.globalAlpha = 1;
    /* правая грань темнее */
    точки(x + шя / 2 - Math.max(1, шя * я.граньСправа), верх,
          Math.max(1, шя * я.граньСправа), вя, цвет(п.деревоТ));
    /* балка поперёк и стойки */
    точки(x - шя / 2, низ - Math.round(вя * я.балкаНа), шя,
          Math.max(1, шя * я.балкаТолщина), цвет(п.деревоТ));
    for (let и = 1; и < я.стоек; и++) {
      точки(x - шя / 2 + шя * и / я.стоек, верх,
            Math.max(1, шя * я.стойкаТолщина), вя, цвет(п.деревоТ));
    }

    окнаЯруса(п, д, x, верх, шя, вя, номер);
    крышаЯруса(п, x, верх, шя, св, вк);
    низ = верх - вк - 1;
  }
}

/*  ТРОПИНКА от кромки дороги к крыльцу. Дугой, с расширением у
    дома: дом не примыкает к тракту вплотную.                     */
function тропинка(п, д, изгиб) {
  const т = НАСТРОЙКИ.холст.дом.тропа;
  const от = серединаДороги(д.y, изгиб) + д.сторона * ширинаДороги(д.y) / 2;
  const до = д.x - д.сторона * д.ш * т.уКрыльца;
  const шагов = Math.max(т.шаговНеМенее, Math.abs(до - от));
  for (let с = 0; с <= шагов; с++) {
    const доля = с / шагов;
    const x = от + (до - от) * доля;
    const y = д.y - Math.sin(доля * Math.PI) * д.ш * т.дуга - доля * т.подъём;
    точки(x, y, Math.max(1, д.ш * т.ширина * доля), 1, цвет(п.тропа));
  }
}

/*  Фонарный столб у начала тропинки. У закрытой лавки погашен, но
    виден: занятость читается видом.                              */
function столб(п, д) {
  const с = НАСТРОЙКИ.холст.дом.столб;
  if (д.ш <= с.мельче) return;
  const сx = Math.round(д.x - д.сторона * д.ш * с.отДома);
  const сy = Math.round(д.y + д.ш * с.наЗемле);
  const вс = Math.round(д.ш * с.высота);
  const гр = Math.max(с.навершиеНеМенее, Math.round(д.ш * с.навершие));
  const верхНавершия = сy - вс - Math.round(гр * с.доляНавершия);

  точки(сx, сy - вс, Math.max(1, Math.round(д.ш * с.толщина)), вс, цвет(п.деревоТ));
  точки(сx - Math.round(гр / 2) + 1, верхНавершия, гр, Math.round(гр * с.доляНавершия),
        д.открыт ? цвет(п.теплоС) : цвет(мешать(п.деревоТ, п.землД, с.погашен)));
  точки(сx - Math.round(гр / 2), верхНавершия - с.крышечка, гр + 1, с.крышечка,
        цвет(п.крыша));
  точки(сx - Math.round(гр / 2), верхНавершия - с.крышечка - 1,
        Math.round((гр + 1) * с.снег), 1, цвет(п.шапка));

  if (д.открыт) {   // тёплое гало и пятно на земле
    кисть.globalAlpha = с.гало;
    точки(сx - гр, сy - вс - гр, гр * 2 + 2, гр * 2 + 2, цвет(п.тепло));
    кисть.globalAlpha = с.пятно;
    точки(сx - гр * с.пятноШирина / 2, сy - 1, гр * с.пятноШирина, с.пятноВысота,
          цвет(п.тепло));
    кисть.globalAlpha = 1;
  }
}

/*  Бумажные фонарики под свесом крыши. Чем ближе дом, тем больше. */
function фонарики(п, д) {
  const ф = НАСТРОЙКИ.холст.дом.фонарик;
  if (д.ш <= ф.мельче) return;
  const я = НАСТРОЙКИ.холст.дом.ярус;
  const фy = Math.round(д.y - д.ш * я.высота - д.ш * я.крыша) + 2;
  const сколько = д.ш > ф.многоОт ? ф.много : (д.ш > ф.среднеОт ? ф.средне : ф.мало);
  for (let и = 0; и < сколько; и++) {
    const фx = Math.round(д.x - д.ш * ф.отступ +
                          и * (д.ш * ф.размах / (сколько - 1 || 1)));
    const р = Math.max(2, Math.round(д.ш * ф.размер));
    точки(фx, фy - ф.подвес, 1, ф.подвес, цвет(п.деревоТ));
    if (д.открыт) {
      const дрожь = (Math.sin((кадр + и * ф.сдвиг) / ф.мерцаниеШаг) + 1) / 2;
      кисть.globalAlpha = ф.свет + дрожь * ф.мерцание;
      точки(фx - Math.round(р / 2), фy, р, р + 1, цвет(п.теплоС));
      точки(фx - Math.round(р / 2), фy + Math.round(р / 2), р, 1, цвет(п.тепло));
      кисть.globalAlpha = ф.гало;
      точки(фx - р, фy - Math.round(р / 2), р * 2, р * 2, цвет(п.тепло));
      кисть.globalAlpha = 1;
    } else {
      точки(фx - Math.round(р / 2), фy, р, р + 1,
            цвет(мешать(п.деревоТ, п.землД, ф.погашен)));
    }
  }
}

/* ═══ 5 · ДЕРЕВЬЯ ══════════════════════════════════════════════════
   Ели и лиственные, вперемешку с домами по глубине: дерево может
   закрыть дом, как в жизни.                                        */

function ель(п, д) {
  const е = НАСТРОЙКИ.холст.дерево.ель, в = д.в, x = д.x, y = д.y;
  точки(x - Math.max(1, в * е.стволТолщина / 2), y - в * е.стволВысота,
        Math.max(1, в * е.стволТолщина), в * е.стволВысота, цвет(п.ствол));
  const ярусов = Math.max(е.ярусовНеМенее, Math.round(в / е.наЯрус));
  for (let я = 0; я < ярусов; я++) {
    const доля = я / ярусов;
    const ш = Math.round(в * е.ярусШирина * (1 - доля * е.ярусСужение));
    const yy = Math.round(y - в * е.ярусСверху - доля * в * е.ярусРазмах);
    const вы = Math.max(2, Math.round(в * е.ярусВысота));
    for (let р = 0; р < вы; р++) {
      const ш2 = Math.round(ш * (1 - р / вы * е.лапаСужение));
      точки(x - ш2 / 2, yy - р, ш2, 1,
            цвет(мешать(п.хвоя, п.хвояС, р / вы * е.светЛапы)));
    }
    кисть.globalAlpha = е.снегСила;      // снег на лапах
    точки(x - ш / 2, yy - вы + 1, Math.round(ш * е.снег), 1, цвет(п.шапка));
    кисть.globalAlpha = 1;
  }
}

function лиственное(п, д) {
  const л = НАСТРОЙКИ.холст.дерево.лист, в = д.в, x = д.x, y = д.y;
  точки(x - Math.max(1, в * л.стволТолщина / 2), y - в * л.стволВысота,
        Math.max(1, в * л.стволТолщина), в * л.стволВысота, цвет(п.ствол));
  /*  Зимой ветви голые. Летом здесь будет крона — она придёт вместе
      со временем года, пятым шагом.                              */
  кисть.strokeStyle = цвет(п.ствол);
  кисть.lineWidth = 1;
  [-1, 1].forEach((сторона) => {
    кисть.beginPath();
    кисть.moveTo(x, y - в * л.стволВысота);
    кисть.lineTo(x + сторона * в * л.ветвьДлина, y - в * л.ветвьВысота);
    кисть.moveTo(x, y - в * (л.стволВысота + л.ветвьОтступ));
    кисть.lineTo(x + сторона * в * л.ветвьВторая, y - в * л.ветвьВтораяВысота);
    кисть.stroke();
  });
  кисть.globalAlpha = л.снегСила;
  точки(x - в * л.снегШирина / 2, y - в * л.снегВысота, в * л.снегШирина, 1,
        цвет(п.шапка));
  кисть.globalAlpha = 1;
}

function дерево(п, д) {
  const т = НАСТРОЙКИ.холст.дерево;
  кисть.globalAlpha = т.тень.сила;
  точки(д.x - д.в * т.тень.доля / 2, д.y - 1, д.в * т.тень.доля, т.тень.высота,
        цвет(п.тень));
  кисть.globalAlpha = 1;
  if (д.ель) ель(п, д); else лиственное(п, д);
}

/*  Деревья расставляются устойчиво: одно и то же дерево на одном и
    том же месте от кадра к кадру. Иначе лес дрожал бы.           */
function поставитьДеревья(изгиб) {
  const х = НАСТРОЙКИ.холст, т = х.дерево;
  const список = [];
  for (let и = 0; и < т.сколько; и++) {
    const глубь = порознь(и, т.сколько);
    const близость = Math.pow(глубь, т.законГлубины);
    const y = Math.round(х.горизонт + х.отступГоризонта +
                         (х.высота - х.горизонт - х.отступГоризонта) * близость);
    const в = Math.round(т.высотаДалеко +
                         (т.высотаБлизко - т.высотаДалеко) * близость);
    const сторона = порознь(и + т.сдвигСтороны, т.сколько) < т.поровну ? -1 : 1;
    const даль = т.отДорогиБлиже +
                 порознь(и + т.сдвигДали, т.сколько) * (т.отДорогиДальше - т.отДорогиБлиже);
    const x = Math.round(серединаДороги(y, изгиб) +
                         сторона * (ширинаДороги(y) / 2 + в * даль));
    список.push({ x: x, y: y, в: в, ель: порознь(и + т.сдвигПороды, т.сколько) < т.доляЕлей });
  }
  return список;
}

/*  Где дом стоит на экране. Дальние выше и мельче, ближние ниже и
    крупнее — по тому же закону, что и дорога.                     */
function поставитьДома(список, изгиб) {
  const х = НАСТРОЙКИ.холст, н = х.дом;
  return список.map((д) => {
    const близость = Math.pow(1 - д.доля, н.законРоста);
    const y = Math.round(х.горизонт + н.отступГоризонта +
                         (х.высота - х.горизонт - н.отступНиза) * близость);
    const ш = Math.round(н.ширинаДалеко +
                         (н.ширинаБлизко - н.ширинаДалеко) * близость);
    const x = Math.round(серединаДороги(y, изгиб) +
                         д.сторона * (ширинаДороги(y) / 2 + ш * н.отступОтДороги));
    return Object.assign({}, д, { x: x, y: y, ш: ш });
  });
}

/* ═══ 5 · ЧТО ВИДНО СНАРУЖИ ════════════════════════════════════════ */

function запуск(узел) {
  холст = узел;
  холст.width = НАСТРОЙКИ.холст.ширина;
  холст.height = НАСТРОЙКИ.холст.высота;
  кисть = холст.getContext('2d');
}

/*  `вид` приходит от карты: { изгиб }. Ничего больше этому файлу
    знать не нужно — он не решает, где герой, он показывает.      */
function рисовать(вид) {
  if (!кисть) return;
  кадр++;
  const к = НАСТРОЙКИ.холст.краски;
  const п = Object.assign({}, к.ночь, к.зима, к.дом);
  const изгиб = вид ? вид.изгиб : 0;
  небо(п);
  земля(п);
  дорога(п, изгиб);
  /*  Дальние рисуются первыми, ближние поверх: так ближний дом
      закрывает дальний, а не наоборот.                          */
  /*  Дома и деревья рисуются ОДНИМ ПОРЯДКОМ по глубине: дальнее
      раньше, ближнее поверх. Оттого дерево может закрыть дом, а не
      висеть перед ним или за ним всегда.                        */
  const дома = поставитьДома((вид && вид.дома) || [], изгиб);
  дома.forEach((д) => тропинка(п, д, изгиб));

  const всё = дома.map((д) => ({ y: д.y, что: () => { дом(п, д); столб(п, д); фонарики(п, д); } }))
    .concat(поставитьДеревья(изгиб).map((д) => ({ y: д.y, что: () => дерево(п, д) })));
  всё.sort((а, б) => а.y - б.y).forEach((что) => что.что());
}

return { запуск: запуск, рисовать: рисовать, глубина: глубина,
         ширинаДороги: ширинаДороги, серединаДороги: серединаДороги };
})();
